function(container, apiUrl, tables) {
  const modal = container.querySelector('#calculation-modal');
  const errorMsg = container.querySelector('#error-message');
  const successMsg = container.querySelector('#success-message');
  const executeBtn = container.querySelector('[data-testid="execute-calculation-button"]');
  const downloadBtn = container.querySelector('[data-testid="download-result-button"]');
  const seasonalCanvas = container.querySelector('#seasonal-chart');
  const weekdayTbody = container.querySelector('#weekday-tbody');

  // テーブルインデックスマッピング
  const tableMap = {};
  tables.forEach((t, idx) => {
    tableMap[t.tableName] = idx;
  });

  // 曜日リスト
  const weekdays = ['月', '火', '水', '木', '金', '土', '日'];

  // メッセージ表示ユーティリティ
  function showError(msg) {
    errorMsg.textContent = msg;
    errorMsg.style.display = 'block';
    setTimeout(() => { errorMsg.style.display = 'none'; }, 4000);
  }

  function showSuccess(msg) {
    successMsg.textContent = msg;
    successMsg.style.display = 'block';
    setTimeout(() => { successMsg.style.display = 'none'; }, 3000);
  }

  // モーダル制御
  function showModal() {
    modal.style.display = 'flex';
  }

  function hideModal() {
    modal.style.display = 'none';
  }

  // モーダル背景クリックで閉じる
  modal.addEventListener('click', (e) => {
    if (e.target === modal) hideModal();
  });

  // Escキーで閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.style.display !== 'none') hideModal();
  });

  // 季節変動グラフ描画
  function drawSeasonalChart(data) {
    const ctx = seasonalCanvas.getContext('2d');
    const width = seasonalCanvas.offsetWidth;
    const height = seasonalCanvas.offsetHeight;
    seasonalCanvas.width = width;
    seasonalCanvas.height = height;

    ctx.fillStyle = '#fef3e2';
    ctx.fillRect(0, 0, width, height);

    // グリッド描画
    ctx.strokeStyle = '#f5d5a8';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = (height / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    // 軸ラベル
    ctx.fillStyle = '#6b7280';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';

    // X軸ラベル（季節）
    const seasons = ['春', '夏', '秋', '冬'];
    const xStep = (width - 60) / seasons.length;
    seasons.forEach((s, i) => {
      ctx.fillText(s, 40 + xStep * (i + 0.5), height - 15);
    });

    // Y軸ラベル
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    for (let i = 0; i <= 5; i++) {
      const val = Math.round((100 / 5) * i);
      const y = height - 30 - (height - 50) * (i / 5);
      ctx.fillText(val, 35, y);
    }

    // データプロット（ダミー）
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2;
    ctx.beginPath();
    const values = [85, 95, 75, 70];
    values.forEach((v, i) => {
      const x = 40 + xStep * (i + 0.5);
      const y = height - 30 - (height - 50) * (v / 100);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // ポイント
    ctx.fillStyle = '#d97706';
    values.forEach((v, i) => {
      const x = 40 + xStep * (i + 0.5);
      const y = height - 30 - (height - 50) * (v / 100);
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // 曜日別傾向テーブル更新
  function updateWeekdayTable(data) {
    weekdayTbody.innerHTML = '';
    weekdays.forEach((day, idx) => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';

      // ダミーデータ生成
      const avgDemand = Math.round(Math.random() * 100 + 50);
      const variance = (Math.random() * 0.3 + 0.1).toFixed(2);
      const index = (Math.random() * 0.4 + 0.8).toFixed(2);

      row.innerHTML = `
        <td style="padding: 6px 8px; color: var(--text); border-right: 1px solid var(--border);">${day}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text); border-right: 1px solid var(--border);">${avgDemand}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text); border-right: 1px solid var(--border);">${variance}</td>
        <td style="padding: 6px 8px; text-align: right; color: var(--text);">${index}</td>
      `;
      weekdayTbody.appendChild(row);
    });
  }

  // 計算実行
  executeBtn.addEventListener('click', async () => {
    const startDate = container.querySelector('[data-testid="start-date-input"]').value;
    const endDate = container.querySelector('[data-testid="end-date-input"]').value;
    const seasonDiv = container.querySelector('[data-testid="season-division-select"]').value;

    if (!startDate || !endDate || !seasonDiv) {
      showError('開始日付、終了日付、季節区分を選択してください');
      return;
    }

    showModal();

    // 計算シミュレーション（実際はAPI呼び出し）
    setTimeout(() => {
      hideModal();
      drawSeasonalChart();
      updateWeekdayTable();
      showSuccess('計算完了しました');
    }, 2000);
  });

  // 結果ダウンロード
  downloadBtn.addEventListener('click', () => {
    const csv = 'BOM曜日,平均需要,変動係数,指数\n';
    let content = csv;
    weekdays.forEach((day, idx) => {
      const row = weekdayTbody.children[idx];
      if (row) {
        const cells = row.querySelectorAll('td');
        content += `${cells[0].textContent},${cells[1].textContent},${cells[2].textContent},${cells[3].textContent}\n`;
      }
    });

    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'seasonal_trend_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
    showSuccess('ダウンロード完了');
  });

  // 初期描画
  drawSeasonalChart();
  updateWeekdayTable();

  // 他画面へのナビゲーション（必要に応じて）
  // 例: 詳細分析へ遷移
  // container.querySelector('#detail-link')?.addEventListener('click', () => {
  //   window.showScreen('scr-1783761972119');
  // });
}
